output.content:
     1|/**
     2| * IVX Autonomous Dashboard — live W1–W12 job ledger (owner-only).
     3| *
     4| * Reads REAL production data from:
     5| *   GET https://api.ivxholding.com/api/ivx/autonomous/ledger
     6| *
     7| * No seed data: every job shown carries a stable job ID, status history with
     8| * timestamps, evidence, and blockers straight from the durable backend ledger.
     9| * Auto-refreshes via controlled polling (30s) + pull-to-refresh.
    10| */
    11|import React, { useState, useCallback, useEffect, useRef } from 'react';
    12|import {
    13|  View,
    14|  Text,
    15|  StyleSheet,
    16|  ScrollView,
    17|  TouchableOpacity,
    18|  ActivityIndicator,
    19|  RefreshControl,
    20|} from 'react-native';
    21|import { SafeAreaView } from 'react-native-safe-area-context';
    22|import { Stack, useRouter } from 'expo-router';
    23|import {
    24|  Activity,
    25|  AlertTriangle,
    26|  ArrowLeft,
    27|  CheckCircle2,
    28|  ChevronDown,
    29|  ChevronRight,
    30|  Clock,
    31|  Cpu,
    32|  ListChecks,
    33|  Lock,
    34|  RefreshCw,
    35|  ShieldCheck,
    36|} from 'lucide-react-native';
    37|import { getIVXAccessToken } from '@/lib/ivx-supabase-client';
    38|
    39|const API_BASE = (process.env.EXPO_PUBLIC_IVX_API_BASE_URL || 'https://api.ivxholding.com').replace(/\/+$/, '');
    40|const LEDGER_URL = `${API_BASE}/api/ivx/autonomous/ledger`;
    41|const GUARDIAN_URL = `${API_BASE}/api/ivx/autonomous/auth-guardian`;
    42|const POLL_INTERVAL_MS = 30_000;
    43|
    44|type LedgerWorker = { id: string; name: string; scope: string };
    45|
    46|type LedgerHistoryEntry = { at: string; from: string | null; to: string; note: string | null };
    47|
    48|type LedgerJob = {
    49|  jobId: string;
    50|  workerId: string;
    51|  title: string;
    52|  status: string;
    53|  priority: string;
    54|  evidence: string | null;
    55|  blocker: string | null;
    56|  createdAt: string;
    57|  updatedAt: string;
    58|  history: LedgerHistoryEntry[];
    59|};
    60|
    61|type LedgerApproval = {
    62|  approvalId: string;
    63|  workerId: string;
    64|  title: string;
    65|  risk: string;
    66|  rollback: string;
    67|  status: string;
    68|  createdAt: string;
    69|};
    70|
    71|type LedgerCounts = {
    72|  workers: number;
    73|  jobs: number;
    74|  verified: number;
    75|  running: number;
    76|  blocked: number;
    77|  ownerActionRequired: number;
    78|  queued: number;
    79|  pendingApprovals: number;
    80|};
    81|
    82|type GuardianProbe = {
    83|  id: string;
    84|  name: string;
    85|  target: string;
    86|  ok: boolean;
    87|  httpStatus: number | null;
    88|  latencyMs: number;
    89|  detail: string;
    90|  checkedAt: string;
    91|};
    92|
    93|type GuardianIncident = {
    94|  incidentId: string;
    95|  probeId: string;
    96|  openedAt: string;
    97|  closedAt: string | null;
    98|  status: string;
    99|  detail: string;
   100|};
   101|
   102|type GuardianAlert = {
   103|  alertId: string;
   104|  severity: string;
   105|  area: string;
   106|  problem: string;
   107|  smsStatus: string;
   108|  messageId: string | null;
   109|  toMasked: string;
   110|  sentAt: string;
   111|  test: boolean;
   112|};
   113|
   114|type GuardianSmsProvider = {
   115|  provider?: string;
   116|  awsCredentialsConfigured?: boolean;
   117|  awsRegion?: string;
   118|  ownerPhoneResolved?: boolean;
   119|  ownerPhoneMasked?: string | null;
   120|  phoneSource?: string;
   121|  ready?: boolean;
   122|};
   123|
   124|type GuardianResponse = {
   125|  ok: boolean;
   126|  error?: string;
   127|  marker?: string;
   128|  generatedAt?: string;
   129|  totalRuns?: number;
   130|  overall?: string;
   131|  probes?: GuardianProbe[];
   132|  openIncidents?: GuardianIncident[];
   133|  recentIncidents?: GuardianIncident[];
   134|  smsProvider?: GuardianSmsProvider;
   135|  recentAlerts?: GuardianAlert[];
   136|};
   137|
   138|type LedgerResponse = {
   139|  ok: boolean;
   140|  error?: string;
   141|  marker?: string;
   142|  generatedAt?: string;
   143|  version?: number;
   144|  updatedAt?: string;
   145|  counts?: LedgerCounts;
   146|  workers?: LedgerWorker[];
   147|  jobs?: LedgerJob[];
   148|  approvals?: LedgerApproval[];
   149|};
   150|
   151|const STATUS_COLORS: Record<string, string> = {
   152|  VERIFIED: '#34D399',
   153|  DONE: '#34D399',
   154|  RUNNING: '#FBBF24',
   155|  QUEUED: '#94A3B8',
   156|  BLOCKED: '#F87171',
   157|  OWNER_ACTION_REQUIRED: '#F97316',
   158|};
   159|
   160|const STATUS_ORDER: string[] = ['RUNNING', 'BLOCKED', 'OWNER_ACTION_REQUIRED', 'QUEUED', 'VERIFIED', 'DONE'];
   161|
   162|function statusColor(status: string): string {
   163|  return STATUS_COLORS[status] ?? '#94A3B8';
   164|}
   165|
   166|function formatTime(iso: string | null | undefined): string {
   167|  if (!iso) return '—';
   168|  try {
   169|    const d = new Date(iso);
   170|    return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
   171|  } catch {
   172|    return iso;
   173|  }
   174|}
   175|
   176|export default function AutonomousDashboardScreen() {
   177|  const router = useRouter();
   178|  const [data, setData] = useState<LedgerResponse | null>(null);
   179|  const [isLoading, setIsLoading] = useState<boolean>(true);
   180|  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
   181|  const [errorMessage, setErrorMessage] = useState<string | null>(null);
   182|  const [isUnauthorized, setIsUnauthorized] = useState<boolean>(false);
   183|  const [expandedJobId, setExpandedJobId] = useState<string | null>(null);
   184|  const [lastFetchedAt, setLastFetchedAt] = useState<string | null>(null);
   185|  const [guardian, setGuardian] = useState<GuardianResponse | null>(null);
   186|  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
   187|
   188|  const fetchLedger = useCallback(async (silent: boolean) => {
   189|    if (!silent) setIsLoading(true);
   190|    setErrorMessage(null);
   191|    try {
   192|      const token = await getIVXAccessToken();
   193|      if (!token) {
   194|        setIsUnauthorized(true);
   195|        setErrorMessage('Owner session required. Sign in as the owner to view the autonomous ledger.');
   196|        return;
   197|      }
   198|      const response = await fetch(LEDGER_URL, {
   199|        method: 'GET',
   200|        headers: { Authorization: `Bearer ${token}` },
   201|      });
   202|      if (response.status === 401 || response.status === 403) {
   203|        setIsUnauthorized(true);
   204|        setErrorMessage('Access denied: this dashboard is restricted to the IVX owner.');
   205|        return;
   206|      }
   207|      const json = (await response.json()) as LedgerResponse;
   208|      if (!json.ok) {
   209|        setErrorMessage(json.error ?? `Ledger request failed (HTTP ${response.status}).`);
   210|        return;
   211|      }
   212|      setIsUnauthorized(false);
   213|      setData(json);
   214|      setLastFetchedAt(new Date().toISOString());
   215|      try {
   216|        const guardianResponse = await fetch(GUARDIAN_URL, {
   217|          method: 'GET',
   218|          headers: { Authorization: `Bearer ${token}` },
   219|        });
   220|        if (guardianResponse.ok) {
   221|          const guardianJson = (await guardianResponse.json()) as GuardianResponse;
   222|          if (guardianJson.ok) setGuardian(guardianJson);
   223|        }
   224|      } catch (guardianError) {
   225|        console.log('[AutonomousDashboard] guardian fetch skipped:', guardianError instanceof Error ? guardianError.message : guardianError);
   226|      }
   227|    } catch (err) {
   228|      const message = err instanceof Error ? err.message : 'Network error loading ledger.';
   229|      console.log('[AutonomousDashboard] fetch failed:', message);
   230|      setErrorMessage(message);
   231|    } finally {
   232|      setIsLoading(false);
   233|      setIsRefreshing(false);
   234|    }
   235|  }, []);
   236|
   237|  useEffect(() => {
   238|    fetchLedger(false);
   239|    pollRef.current = setInterval(() => fetchLedger(true), POLL_INTERVAL_MS);
   240|    return () => {
   241|      if (pollRef.current) clearInterval(pollRef.current);
   242|    };
   243|  }, [fetchLedger]);
   244|
   245|  const onRefresh = useCallback(() => {
   246|    setIsRefreshing(true);
   247|    fetchLedger(true);
   248|  }, [fetchLedger]);
   249|
   250|  const counts = data?.counts;
   251|  const jobs = data?.jobs ?? [];
   252|  const workers = data?.workers ?? [];
   253|  const approvals = (data?.approvals ?? []).filter((a) => a.status === 'PENDING');
   254|  const sortedJobs = [...jobs].sort((a, b) => {
   255|    const sa = STATUS_ORDER.indexOf(a.status);
   256|    const sb = STATUS_ORDER.indexOf(b.status);
   257|    if (sa !== sb) return sa - sb;
   258|    return a.jobId.localeCompare(b.jobId);
   259|  });
   260|  const completionPercent = counts && counts.jobs > 0 ? Math.round((counts.verified / counts.jobs) * 100) : 0;
   261|
   262|  return (
   263|    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
   264|      <Stack.Screen options={{ headerShown: false }} />
   265|      <View style={styles.header}>
   266|        <TouchableOpacity onPress={() => router.back()} style={styles.backButton} testID="autonomous-dashboard-back">
   267|          <ArrowLeft size={22} color="#E2E8F0" />
   268|        </TouchableOpacity>
   269|        <View style={styles.headerTitleWrap}>
   270|          <Text style={styles.headerTitle}>Autonomous Dashboard</Text>
   271|          <Text style={styles.headerSubtitle}>
   272|            Live ledger · v{data?.version ?? '—'} · {formatTime(lastFetchedAt)}
   273|          </Text>
   274|        </View>
   275|        <TouchableOpacity onPress={onRefresh} style={styles.refreshButton} testID="autonomous-dashboard-refresh">
   276|          <RefreshCw size={18} color="#FBBF24" />
   277|        </TouchableOpacity>
   278|      </View>
   279|
   280|      {isLoading ? (
   281|        <View style={styles.centerFill}>
   282|          <ActivityIndicator size="large" color="#FBBF24" />
   283|          <Text style={styles.loadingText}>Loading live job ledger…</Text>
   284|        </View>
   285|      ) : isUnauthorized ? (
   286|        <View style={styles.centerFill}>
   287|          <Lock size={40} color="#F87171" />
   288|          <Text style={styles.errorTitle}>Owner access required</Text>
   289|          <Text style={styles.errorBody}>{errorMessage}</Text>
   290|        </View>
   291|      ) : errorMessage && !data ? (
   292|        <View style={styles.centerFill}>
   293|          <AlertTriangle size={40} color="#F87171" />
   294|          <Text style={styles.errorTitle}>Could not load ledger</Text>
   295|          <Text style={styles.errorBody}>{errorMessage}</Text>
   296|          <TouchableOpacity style={styles.retryButton} onPress={() => fetchLedger(false)}>
   297|            <Text style={styles.retryText}>Retry</Text>
   298|          </TouchableOpacity>
   299|        </View>
   300|      ) : (
   301|        <ScrollView
   302|          style={styles.scroll}
   303|          contentContainerStyle={styles.scrollContent}
   304|          refreshControl={<RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} tintColor="#FBBF24" />}
   305|        >
   306|          {counts ? (
   307|            <View style={styles.card}>
   308|              <View style={styles.cardHeaderRow}>
   309|                <Activity size={16} color="#FBBF24" />
   310|                <Text style={styles.cardHeader}>Overview</Text>
   311|              </View>
   312|              <View style={styles.progressTrack}>
   313|                <View style={[styles.progressFill, { width: `${completionPercent}%` }]} />
   314|              </View>
   315|              <Text style={styles.progressLabel}>{completionPercent}% verified ({counts.verified}/{counts.jobs} jobs)</Text>
   316|              <View style={styles.statGrid}>
   317|                <StatPill label="Running" value={counts.running} color="#FBBF24" />
   318|                <StatPill label="Blocked" value={counts.blocked} color="#F87171" />
   319|                <StatPill label="Owner action" value={counts.ownerActionRequired} color="#F97316" />
   320|                <StatPill label="Queued" value={counts.queued} color="#94A3B8" />
   321|                <StatPill label="Workers" value={counts.workers} color="#60A5FA" />
   322|                <StatPill label="Approvals" value={counts.pendingApprovals} color="#F97316" />
   323|              </View>
   324|            </View>
   325|          ) : null}
   326|
   327|          {approvals.length > 0 ? (
   328|            <View style={styles.card}>
   329|              <View style={styles.cardHeaderRow}>
   330|                <ShieldCheck size={16} color="#F97316" />
   331|                <Text style={styles.cardHeader}>Approvals waiting ({approvals.length})</Text>
   332|              </View>
   333|              {approvals.map((approval) => (
   334|                <View key={approval.approvalId} style={styles.approvalRow}>
   335|                  <Text style={styles.approvalTitle}>{approval.approvalId} · {approval.title}</Text>
   336|                  <Text style={styles.approvalMeta}>Risk: {approval.risk}</Text>
   337|                  <Text style={styles.approvalMeta}>Rollback: {approval.rollback}</Text>
   338|                </View>
   339|              ))}
   340|            </View>
   341|          ) : null}
   342|
   343|          {guardian ? (
   344|            <View style={styles.card}>
   345|              <View style={styles.cardHeaderRow}>
   346|                <ShieldCheck size={16} color={guardian.overall === 'HEALTHY' ? '#34D399' : '#F87171'} />
   347|                <Text style={styles.cardHeader}>Owner Authentication</Text>
   348|                <Text style={[styles.guardianBadge, { color: guardian.overall === 'HEALTHY' ? '#34D399' : '#F87171' }]}>
   349|                  {guardian.overall ?? '—'}
   350|                </Text>
   351|              </View>
   352|              <Text style={styles.guardianMeta}>
   353|                Auth Guardian · run #{guardian.totalRuns ?? 0} · {formatTime(guardian.generatedAt)}
   354|              </Text>
   355|              {(guardian.probes ?? []).map((probe) => (
   356|                <View key={probe.id} style={styles.probeRow}>
   357|                  <View style={[styles.statusDot, { backgroundColor: probe.ok ? '#34D399' : '#F87171' }]} />
   358|                  <View style={styles.probeTextWrap}>
   359|                    <Text style={styles.probeName}>{probe.name}</Text>
   360|                    <Text style={styles.probeDetail}>
   361|                      HTTP {probe.httpStatus ?? '—'} · {probe.latencyMs}ms · {probe.detail}
   362|                    </Text>
   363|                  </View>
   364|                </View>
   365|              ))}
   366|              {(guardian.openIncidents ?? []).length > 0 ? (
   367|                <View style={styles.incidentBox}>
   368|                  <Text style={styles.incidentHeader}>Open incidents</Text>
   369|                  {(guardian.openIncidents ?? []).map((incident) => (
   370|                    <Text key={incident.incidentId} style={styles.jobBlocker}>
   371|                      {incident.incidentId} · {incident.detail} · opened {formatTime(incident.openedAt)}
   372|                    </Text>
   373|                  ))}
   374|                </View>
   375|              ) : (
   376|                <Text style={styles.jobEvidence}>No open authentication incidents.</Text>
   377|              )}
   378|              <View style={styles.smsBox}>
   379|                <Text style={styles.smsHeader}>
   380|                  SMS alerts ({guardian.smsProvider?.provider ?? 'aws_sns'}) — {guardian.smsProvider?.ready ? 'READY' : 'NOT READY'}
   381|                </Text>
   382|                <Text style={styles.probeDetail}>
   383|                  AWS creds: {guardian.smsProvider?.awsCredentialsConfigured ? 'configured' : 'MISSING on backend'} · phone: {guardian.smsProvider?.ownerPhoneMasked ?? '—'} ({guardian.smsProvider?.phoneSource ?? '—'})
   384|                </Text>
   385|                {(guardian.recentAlerts ?? []).slice(0, 3).map((alert) => (
   386|                  <Text key={alert.alertId} style={styles.probeDetail}>
   387|                    {alert.alertId} · {alert.severity} · {alert.smsStatus}
   388|                    {alert.messageId ? ` · id ${alert.messageId.slice(0, 8)}…` : ''} · {formatTime(alert.sentAt)}
   389|                  </Text>
   390|                ))}
   391|              </View>
   392|            </View>
   393|          ) : null}
   394|
   395|          <View style={styles.card}>
   396|            <View style={styles.cardHeaderRow}>
   397|              <ListChecks size={16} color="#60A5FA" />
   398|              <Text style={styles.cardHeader}>Jobs ({sortedJobs.length})</Text>
   399|            </View>
   400|            {sortedJobs.length === 0 ? (
   401|              <Text style={styles.emptyText}>No jobs in the ledger yet.</Text>
   402|            ) : (
   403|              sortedJobs.map((job) => {
   404|                const expanded = expandedJobId === job.jobId;
   405|                return (
   406|                  <TouchableOpacity
   407|                    key={job.jobId}
   408|                    style={styles.jobRow}
   409|                    onPress={() => setExpandedJobId(expanded ? null : job.jobId)}
   410|                    testID={`job-${job.jobId}`}
   411|                  >
   412|                    <View style={styles.jobTopRow}>
   413|                      <View style={[styles.statusDot, { backgroundColor: statusColor(job.status) }]} />
   414|                      <Text style={styles.jobId}>{job.jobId}</Text>
   415|                      <Text style={[styles.jobStatus, { color: statusColor(job.status) }]}>{job.status}</Text>
   416|                      <Text style={styles.jobPriority}>{job.priority}</Text>
   417|                      <Text style={styles.jobWorker}>{job.workerId}</Text>
   418|                      {expanded ? <ChevronDown size={14} color="#64748B" /> : <ChevronRight size={14} color="#64748B" />}
   419|                    </View>
   420|                    <Text style={styles.jobTitle}>{job.title}</Text>
   421|                    {expanded ? (
   422|                      <View style={styles.jobDetail}>
   423|                        {job.evidence ? <Text style={styles.jobEvidence}>Evidence: {job.evidence}</Text> : null}
   424|                        {job.blocker ? <Text style={styles.jobBlocker}>Blocker: {job.blocker}</Text> : null}
   425|                        <Text style={styles.jobMeta}>Updated: {formatTime(job.updatedAt)}</Text>
   426|                        {job.history.map((entry, index) => (
   427|                          <View key={`${job.jobId}-h${index}`} style={styles.historyRow}>
   428|                            <Clock size={11} color="#64748B" />
   429|                            <Text style={styles.historyText}>
   430|                              {formatTime(entry.at)} · {entry.from ?? 'START'} → {entry.to}
   431|                              {entry.note ? ` · ${entry.note}` : ''}
   432|                            </Text>
   433|                          </View>
   434|                        ))}
   435|                      </View>
   436|                    ) : null}
   437|                  </TouchableOpacity>
   438|                );
   439|              })
   440|            )}
   441|          </View>
   442|
   443|          <View style={styles.card}>
   444|            <View style={styles.cardHeaderRow}>
   445|              <Cpu size={16} color="#34D399" />
   446|              <Text style={styles.cardHeader}>Workers ({workers.length})</Text>
   447|            </View>
   448|            {workers.map((worker) => {
   449|              const workerJobs = jobs.filter((j) => j.workerId === worker.id);
   450|              const active = workerJobs.find((j) => j.status === 'RUNNING');
   451|              return (
   452|                <View key={worker.id} style={styles.workerRow}>
   453|                  <View style={styles.workerTopRow}>
   454|                    <Text style={styles.workerId}>{worker.id}</Text>
   455|                    <Text style={styles.workerName}>{worker.name}</Text>
   456|                    {active ? <CheckCircle2 size={13} color="#FBBF24" /> : null}
   457|                  </View>
   458|                  <Text style={styles.workerScope}>{worker.scope}</Text>
   459|                  <Text style={styles.workerMeta}>
   460|                    {workerJobs.length} jobs · {workerJobs.filter((j) => j.status === 'VERIFIED' || j.status === 'DONE').length} verified
   461|                    {active ? ` · running: ${active.jobId}` : ''}
   462|                  </Text>
   463|                </View>
   464|              );
   465|            })}
   466|          </View>
   467|
   468|          <Text style={styles.footerNote}>
   469|            Source: {data?.marker ?? '—'} · durable backend ledger · auto-refresh every 30s
   470|          </Text>
   471|        </ScrollView>
   472|      )}
   473|    </SafeAreaView>
   474|  );
   475|}
   476|
   477|function StatPill({ label, value, color }: { label: string; value: number; color: string }) {
   478|  return (
   479|    <View style={styles.statPill}>
   480|      <Text style={[styles.statValue, { color }]}>{value}</Text>
   481|      <Text style={styles.statLabel}>{label}</Text>
   482|    </View>
   483|  );
   484|}
   485|
   486|const styles = StyleSheet.create({
   487|  safeArea: { flex: 1, backgroundColor: '#0B1220' },
   488|  header: {
   489|    flexDirection: 'row',
   490|    alignItems: 'center',
   491|    paddingHorizontal: 16,
   492|    paddingVertical: 12,
   493|    borderBottomWidth: StyleSheet.hairlineWidth,
   494|    borderBottomColor: '#1E293B',
   495|  },
   496|  backButton: { padding: 6, marginRight: 6 },
   497|  headerTitleWrap: { flex: 1 },
   498|  headerTitle: { color: '#F1F5F9', fontSize: 18, fontWeight: '700' as const },
   499|  headerSubtitle: { color: '#64748B', fontSize: 11, marginTop: 2 },
   500|  refreshButton: { padding: 8 },
   501|  centerFill: { flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 32, gap: 10 },
   502|  loadingText: { color: '#94A3B8', fontSize: 14 },
   503|  errorTitle: { color: '#F1F5F9', fontSize: 17, fontWeight: '700' as const },
   504|  errorBody: { color: '#94A3B8', fontSize: 13, textAlign: 'center' as const },
   505|  retryButton: { marginTop: 8, backgroundColor: '#FBBF24', borderRadius: 8, paddingHorizontal: 20, paddingVertical: 10 },
   506|  retryText: { color: '#0B1220', fontWeight: '700' as const },
   507|  scroll: { flex: 1 },
   508|  scrollContent: { padding: 16, paddingBottom: 40, gap: 14 },
   509|  card: { backgroundColor: '#111A2C', borderRadius: 14, padding: 14, borderWidth: 1, borderColor: '#1E293B' },
